    seo: { metaTitle: 'Salud de cuenta en Amazon y rentabilidad: dos revisiones diferentes', metaDescription: 'Distingue salud de cuenta y rentabilidad en Amazon: políticas, avisos, costes y continuidad para no confundir un panel sin alertas con un negocio sólido.' },
